using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using System.ComponentModel;
using System.Text.Json;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

builder.Services.AddSingleton<ResearchTools>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();

// Build the agent with tools
var agent = new ChatClientAgent(chatClient,
    "ResearchAgent",
    """
    You are a research agent. Your job is to research a topic by searching the web,
    taking notes on important findings, and then providing a comprehensive summary.

    Workflow:
    1. Search the web for relevant information on the given topic.
    2. Take notes on key findings using the note-taking tool.
    3. Perform additional searches to fill gaps or explore subtopics.
    4. Once you have enough information, provide a final summary of your research.

    Always take notes before summarizing so you have a structured record of findings.
    """)
{
    Tools = [.. AIFunctionFactory.Create(researchTools)],
};

// Run the research loop
Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n=== Research Notes ===");
foreach (var note in researchTools.GetNotes())
{
    Console.WriteLine($"- {note}");
}

/// <summary>
/// Tools available to the research agent for web searching and note-taking.
/// </summary>
public sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private static readonly HttpClient s_httpClient = new()
    {
        Timeout = TimeSpan.FromSeconds(15)
    };

    [Description("Search the web for information on a query. Returns relevant search results with titles and snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up")] string query,
        [Description("Maximum number of results to return (1-5)")] int maxResults = 3)
    {
        maxResults = Math.Clamp(maxResults, 1, 5);

        try
        {
            // Use a public search API (DuckDuckGo instant answer API)
            var encodedQuery = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encodedQuery}&format=json&no_html=1&skip_disambig=1";

            var response = await s_httpClient.GetStringAsync(url);
            var doc = JsonDocument.Parse(response);
            var root = doc.RootElement;

            var results = new List<string>();

            // Get abstract if available
            var abstractText = root.GetProperty("Abstract").GetString();
            var abstractSource = root.GetProperty("AbstractSource").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.Add($"[{abstractSource}] {abstractText}");
            }

            // Get related topics
            if (root.TryGetProperty("RelatedTopics", out var topics) &&
                topics.ValueKind == JsonValueKind.Array)
            {
                foreach (var topic in topics.EnumerateArray().Take(maxResults))
                {
                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        results.Add(text);
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No results found for '{query}'. Try refining the search terms.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note. Use this to record important findings during research.")]
    public string TakeNote(
        [Description("The note content to save")] string content,
        [Description("A short label or category for the note")] string label = "General")
    {
        var note = $"[{label}] {content}";
        _notes.Add(note);
        return $"Note saved ({_notes.Count} total): [{label}] {content[..Math.Min(content.Length, 80)]}...";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return $"Saved notes ({_notes.Count}):\n" + string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }

    public IReadOnlyList<string> GetNotes() => _notes.AsReadOnly();
}

